var ITEMS=[["What farriers do","Farriers trim and shoe horse hooves: balancing feet, forging shoes, and correcting lameness issues with veterinarians. It is blacksmithing plus anatomy \u2014 physical, skilled, and well-paid for certified practitioners."], ["Essential tools","Hoof nippers, rasp, hoof knife, hammer, anvil or shoeing box, forge (gas or coal), tongs, pritchel, clinch cutter, hoof stand, and apron with chaps. Truck setup matters \u2014 you travel to the horses."], ["Key skills","Reading hoof balance and conformation. Trimming to correct angles. Forging shoes to fit (no two feet alike). Hot shoeing: burning the shoe to seat it. Nailing without quicking. Working safely around 500-kg animals."], ["Safety essentials","Horses kick: position to the side, never behind. Read the horse before touching. Steel-toe boots. Forge burns: tongs and gloves always. Back care: shoeing is brutal on the spine \u2014 lift and stretch."], ["Getting started","Farrier schools teach basics in months; apprenticeship with a master teaches the rest. Certifications (AFA) build credibility. Start with calm horses; difficult ones come with experience."], ["Pro tips","Be on time \u2014 horse people talk. Handle feet quietly and confidently. Keep detailed shoeing records per horse. Charge for your knowledge, not just your time. Stay fit; this trade punishes the unfit."], ["Nippers","Trade term \u2014 Nippers: The trimmers cutting hoof wall."], ["Rasp","Trade term \u2014 Rasp: The file leveling the hoof."], ["Hoof knife","Trade term \u2014 Hoof knife: The blade paring sole and frog."], ["Frog","Trade term \u2014 Frog: The V-shaped cushion of the hoof underside."], ["Wall","Trade term \u2014 Wall: The outer hoof horn."], ["Sole","Trade term \u2014 Sole: The hoof underside."], ["Coronet band","Trade term \u2014 Coronet band: Where hoof growth originates."], ["Quick","Trade term \u2014 Quick: The live tissue inside; nailing it causes pain."], ["Hot shoeing","Trade term \u2014 Hot shoeing: Fitting shoes heated and burned to seat."], ["Cold shoeing","Trade term \u2014 Cold shoeing: Fitting pre-made shoes without heat."], ["Keg shoe","Trade term \u2014 Keg shoe: Factory-made horseshoe."], ["Handmade shoe","Trade term \u2014 Handmade shoe: Forged to the individual hoof."], ["Clinch","Trade term \u2014 Clinch: The bent-over nail end holding the shoe."], ["Pritchel","Trade term \u2014 Pritchel: The punch making nail holes."], ["Anvil","Trade term \u2014 Anvil: The forging surface."], ["Forge","Trade term \u2014 Forge: The heating furnace."], ["Tongs","Trade term \u2014 Tongs: Holding hot metal."], ["Balance","Trade term \u2014 Balance: Correct hoof angles and symmetry."], ["Laminitis","Trade term \u2014 Laminitis: The serious hoof disease; farrier-vet teamwork."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
